// School catalogue: the studio's schools, their teachers with portraits, and teachers chosen for an order.
// Uses the shared helpers from v2.js (api, json, esc, toast, count, svgIcon, searchKey, routeVersion).
const SchoolCatalog=(()=>{
  let query='',city='',catalogView='grid';
  try{if(localStorage.getItem('schoolsView')==='list')catalogView='list';}catch{}
  const cityKey=value=>String(value||'').trim().replace(/\s+/g,' ').toLocaleLowerCase('ru').replace(/ё/g,'е')||'__missing';
  const teacherLabel=n=>count(n,'учитель','учителя','учителей');
  const orderLabel=n=>count(n,'заказ','заказа','заказов');
  const initials=t=>[t.last_name,t.first_name].map(x=>(x||'').charAt(0)).join('').toUpperCase()||'?';
  const portraitUrl=t=>`/api/teachers/${encodeURIComponent(t.id)}/portrait/thumb?v=${encodeURIComponent(t.portrait_version)}`;
  const avatar=t=>t.has_portrait?`<img src="${portraitUrl(t)}" alt="" loading="lazy">`:`<span class="teacher-initials" aria-hidden="true">${esc(initials(t))}</span>`;
  const place=s=>s.city?esc(s.city):'<span class="muted">Город не указан</span>';

  function schoolForm(school){
    $('#action-content').onclick=null;$('#action-content').onchange=null;
    $('#action-dialog').classList.remove('wide-dialog');
    $('#action-content').innerHTML=`<form id="school-form"><div class="dialog-heading"><h2>${school?'Изменить школу':'Новая школа'}</h2><button type="button" class="close" data-close="action-dialog" aria-label="Закрыть">×</button></div><label>Полное название<input name="name" maxlength="300" required placeholder="МБОУ «Средняя общеобразовательная школа № 5»" value="${esc(school?.name||'')}"></label><label>Краткое название<input name="short_name" maxlength="100" placeholder="Школа № 5" value="${esc(school?.short_name||'')}" autocomplete="off"></label><label>Город<input name="city" maxlength="100" required placeholder="Казань" value="${esc(school?.city||'')}" autocomplete="address-level2"></label><p class="error" role="alert"></p><button class="primary wide" type="submit">${school?'Сохранить':'Добавить школу'}</button></form>`;
    $('#action-dialog').showModal();
    const form=$('#school-form');form.elements.name.focus();
    form.onsubmit=async e=>{e.preventDefault();const button=form.querySelector('[type=submit]'),values=Object.fromEntries(new FormData(form));button.disabled=true;try{const saved=await api('/schools'+(school?'/'+school.id:''),json(school?'PATCH':'POST',values));$('#action-dialog').close();toast(school?'Школа сохранена':'Школа добавлена');if(school)await schoolPage(school.id);else location.hash='schools/'+saved.id;}catch(error){form.querySelector('.error').textContent=error.message;button.disabled=false;}};
  }

  let schoolEdit=null;
  function stopSchoolEdit(){
    if(!schoolEdit)return;
    const {card,form}=schoolEdit;schoolEdit=null;
    form.remove();card.classList.remove('editing');
    const link=card.querySelector('.order-tile-main');link.removeAttribute('tabindex');link.removeAttribute('aria-hidden');
    card.querySelector('.design-menu').hidden=false;
  }
  async function saveSchoolEdit(){
    if(!schoolEdit||schoolEdit.saving)return;
    const edit=schoolEdit,{form,school}=edit;
    if(!form.reportValidity())return;
    const values=Object.fromEntries(new FormData(form));
    for(const key of Object.keys(values))values[key]=values[key].trim();
    if(!values.name||!values.city){form.querySelector(`[name="${!values.name?'name':'city'}"]`).focus();return;}
    if(Object.entries(values).every(([key,value])=>value===(school[key]||''))){stopSchoolEdit();return;}
    edit.saving=true;form.querySelector('[type=submit]').disabled=true;
    try{const saved=await api('/schools/'+encodeURIComponent(school.id),json('PATCH',values));Object.assign(school,saved);if(schoolEdit===edit){stopSchoolEdit();if(edit.card.isConnected)await listPage();}toast('Школа сохранена');}
    catch(error){form.querySelector('.error').textContent=error.message;}
    finally{edit.saving=false;form.querySelector('[type=submit]').disabled=false;}
  }
  function editSchoolCard(card,school){
    stopSchoolEdit();card.classList.add('editing');
    const link=card.querySelector('.order-tile-main');link.tabIndex=-1;link.setAttribute('aria-hidden','true');card.querySelector('.design-menu').hidden=true;
    card.insertAdjacentHTML('beforeend',`<form class="school-card-edit"><input name="name" maxlength="300" required value="${esc(school.name)}" aria-label="Полное название школы" placeholder="Полное название"><input name="short_name" maxlength="100" value="${esc(school.short_name||'')}" aria-label="Краткое название школы" placeholder="Краткое название"><input name="city" maxlength="100" required value="${esc(school.city||'')}" aria-label="Город школы" placeholder="Город"><p class="error" role="alert"></p><div class="folder-edit-actions"><button type="button" class="secondary" data-school-edit-cancel>Отмена</button><button type="submit" class="primary">Сохранить</button></div></form>`);
    const form=card.querySelector('.school-card-edit');schoolEdit={card,form,school,saving:false};
    form.onsubmit=e=>{e.preventDefault();saveSchoolEdit();};
    form.querySelector('[data-school-edit-cancel]').onclick=()=>{if(!schoolEdit?.saving)stopSchoolEdit();};
    form.onkeydown=e=>{if(e.key==='Escape'){e.preventDefault();if(!schoolEdit?.saving)stopSchoolEdit();}};
    form.elements.name.focus();form.elements.name.select();
  }
  document.addEventListener('pointerdown',e=>{if(!schoolEdit)return;if(!schoolEdit.card.isConnected){schoolEdit=null;return;}if(!schoolEdit.card.contains(e.target))saveSchoolEdit();});

  function drawList(schools){
    const el=$('#school-list');if(!el)return;stopSchoolEdit();const q=searchKey(query);
    const rows=schools.filter(s=>(!city||cityKey(s.city)===city)&&(!q||searchKey([s.name,s.short_name,s.city].filter(Boolean).join(' ')).includes(q)));
    const chip=$('#school-city-chip'),select=$('#school-city');
    if(chip&&select){chip.classList.toggle('set',!!city);chip.querySelector('.chip-label').textContent=select.selectedOptions[0]?.textContent||'Город';}
    el.className=catalogView==='list'?'queue-list school-rows':'school-list';
    el.innerHTML=(rows.length&&catalogView==='list'?'<div class="queue-table-head school-table-head"><span>Школа</span><span>Город</span><span>Учителя</span><span>Заказы</span><span></span></div>':'')+rows.map(s=>catalogView==='list'?`<article class="queue-row school-tile school-row"><a class="queue-name order-tile-main" href="#schools/${encodeURIComponent(s.id)}"><strong class="school-row-name">${esc(s.short_name||s.name)}</strong></a><span class="school-row-city">${place(s)}</span><span class="queue-num school-row-count">${teacherLabel(s.teacher_count)}</span><span class="queue-num school-row-count">${orderLabel(s.order_count)}</span><div class="design-menu school-row-menu"><button type="button" class="design-menu-toggle" data-v2="design-menu" aria-haspopup="menu" aria-expanded="false" aria-label="Действия со школой ${esc(s.name)}">${svgIcon('more',18)}</button><div class="design-menu-list" role="menu" hidden><button type="button" role="menuitem" data-school-edit="${esc(s.id)}">${svgIcon('edit',16)} Изменить школу</button></div></div></article>`:`<article class="order-tile school-tile"><a class="order-tile-main" href="#schools/${encodeURIComponent(s.id)}"><div class="order-preview">${s.previews?.length?`<span class="order-preview-fan count-${s.previews.length}">${s.previews.map(t=>`<img src="${portraitUrl(t)}" alt="" loading="lazy">`).join('')}</span>`:`<span class="order-preview-paper school-preview-paper" aria-hidden="true"><small>${esc(s.city||'')}</small><strong>${esc(s.short_name||s.name)}</strong><i></i></span>`}<span class="order-tile-content"><span class="order-tile-text"><strong class="school-tile-name">${esc(s.short_name||s.name)}</strong><small class="order-tile-stage">${place(s)}</small></span></span></div><span class="school-tile-meta"><span>${svgIcon('users',15)} ${teacherLabel(s.teacher_count)}</span><span>${svgIcon('folder',15)} ${orderLabel(s.order_count)}</span></span></a><div class="design-menu order-tile-menu"><button type="button" class="design-menu-toggle" data-v2="design-menu" aria-haspopup="menu" aria-expanded="false" aria-label="Действия со школой ${esc(s.name)}">${svgIcon('more',18)}</button><div class="design-menu-list" role="menu" hidden><button type="button" role="menuitem" data-school-edit="${esc(s.id)}">${svgIcon('edit',16)} Изменить школу</button></div></div></article>`).join('')||`<div class="empty-state"><h3>${schools.length?'Школы не найдены':'Школ пока нет'}</h3><p>${schools.length?'Измените поиск или сбросьте фильтр города.':'Добавьте школу, затем её учителей. Учителя сохраняются и подходят для всех заказов этой школы.'}</p></div>`;
    el.onclick=e=>{const edit=e.target.closest('[data-school-edit]');if(edit){closeDesignMenus();editSchoolCard(edit.closest('.school-tile'),schools.find(s=>s.id===edit.dataset.schoolEdit));}};
  }

  async function listPage(){
    const version=routeVersion;
    $('#main').innerHTML=`<div class="page schools-page registry"><div class="queue-head"><h1>Каталог школ</h1><div class="queue-tools"><div id="school-filter-bar" hidden></div><label class="queue-search ${query?'open':''}"><button type="button" id="school-search-toggle" title="Поиск" aria-label="Поиск">${svgIcon('search',16)}</button><input id="school-query" type="search" aria-label="Поиск школы" placeholder="Название или город" value="${esc(query)}"></label><div class="segmented" role="group" aria-label="Вид школ"><button type="button" data-schools-view="list" aria-label="Строки" title="Список" aria-pressed="${catalogView==='list'}">${svgIcon('list',16)}</button><button type="button" data-schools-view="grid" aria-label="Карточки" title="Плитка" aria-pressed="${catalogView==='grid'}">${svgIcon('grid',16)}</button></div><button class="primary" data-school="new">＋ Добавить школу</button></div></div><p class="muted school-catalog-description">Ваши школы и учителя. Их видит только ваша студия; класс выбирает учителей для своего альбома.</p><div id="school-list" class="school-list" aria-live="polite"><p class="muted">Загружаем школы…</p></div></div>`;
    const input=$('#school-query');
    $('#school-search-toggle').onclick=()=>{input.parentElement.classList.add('open');input.focus();};
    input.onblur=()=>{if(!input.value)input.parentElement.classList.remove('open');};
    let schools;try{schools=await api('/schools');}catch(error){if(version===routeVersion)$('#school-list').innerHTML=`<p class="error">${esc(error.message)}</p>`;return;}
    if(version!==routeVersion)return;
    const cities=[...new Map(schools.map(s=>[cityKey(s.city),String(s.city||'').trim()||'Город не указан'])).entries()].sort((a,b)=>a[1].localeCompare(b[1],'ru'));
    if(!cities.some(([key])=>key===city))city='';
    if(cities.length>1){
      const bar=$('#school-filter-bar');bar.hidden=false;
      bar.innerHTML=`<div class="registry-filters"><span class="filter-chip" data-chip="city" id="school-city-chip">${svgIcon('city',15)}<span class="chip-label">Город</span><select id="school-city" aria-label="Город"><option value="" data-menu-label="Все города">Город</option>${cities.map(([key,label])=>`<option value="${esc(key)}" ${city===key?'selected':''}>${esc(label)}</option>`).join('')}</select><button type="button" class="chip-clear" id="school-city-clear" aria-label="Сбросить: Город">×</button></span></div>`;
      $('#school-city').onchange=e=>{city=e.target.value;drawList(schools);};
      $('#school-city-clear').onclick=()=>{city='';$('#school-city').value='';drawList(schools);$('#school-city').focus();};
    }else city='';
    input.oninput=()=>{query=input.value;drawList(schools);};
    input.onkeydown=e=>{if(e.key==='Escape'){input.value='';query='';input.blur();drawList(schools);}};
    document.querySelectorAll('[data-schools-view]').forEach(button=>button.onclick=()=>{catalogView=button.dataset.schoolsView;try{localStorage.setItem('schoolsView',catalogView);}catch{}document.querySelectorAll('[data-schools-view]').forEach(b=>b.setAttribute('aria-pressed',String(b===button)));drawList(schools);});
    drawList(schools);
  }

  function teacherFields(t={}){
    return `<label>Фамилия<input name="last_name" maxlength="60" required value="${esc(t.last_name||'')}" autocomplete="off"></label><label>Имя<input name="first_name" maxlength="60" value="${esc(t.first_name||'')}" autocomplete="off"></label><label>Отчество<input name="patronymic" maxlength="60" value="${esc(t.patronymic||'')}" autocomplete="off"></label><label>Предмет или должность<input name="subject" maxlength="100" value="${esc(t.subject||'')}" placeholder="Математика" autocomplete="off"></label>`;
  }

  function teacherCard(t){
    return `<article class="teacher-card" data-teacher="${esc(t.id)}"><div class="teacher-photo">${avatar(t)}</div><div class="teacher-text"><strong>${esc(t.name)}</strong><small>${esc(t.subject)||'Предмет не указан'}</small>${t.archived?'<small>В архиве</small>':''}${t.portrait_by==='client'?'<small class="teacher-by">Подписано классом</small>':''}${t.portrait_at?`<small>Портрет: ${new Date(t.portrait_at).toLocaleDateString('ru-RU')}</small>`:t.has_portrait?'<small>Дата портрета неизвестна</small>':'<small>Нет портрета</small>'}</div><div class="teacher-actions">${t.has_portrait?`<a class="text-button" href="/api/teachers/${encodeURIComponent(t.id)}/portrait/full?v=${encodeURIComponent(t.portrait_version)}" download="${esc(t.name)}.jpg">${svgIcon('download',14)} Скачать</a>`:''}${t.archived?`<button type="button" class="text-button" data-teacher-restore="${esc(t.id)}">Восстановить</button>`:`<label class="text-button teacher-upload">${t.has_portrait?'Заменить фото':'Загрузить фото'}<input type="file" accept="image/jpeg,image/png" data-teacher-photo="${esc(t.id)}" hidden></label><button type="button" class="text-button" data-teacher-edit="${esc(t.id)}">Изменить</button><button type="button" class="text-button" data-teacher-delete="${esc(t.id)}">В архив</button>`}<button type="button" class="text-button" data-teacher-merge="${esc(t.id)}">Объединить…</button></div></article>`;
  }

  const schoolViews=new Map();
  function teacherEditor(school,t=null,refresh=()=>schoolPage(school.id)){
    $('#action-content').onclick=null;$('#action-content').onchange=null;
    $('#action-dialog').classList.remove('wide-dialog');
    $('#action-content').innerHTML=`<form id="teacher-edit"><div class="dialog-heading"><h2>${t?'Изменить учителя':'Добавить учителя'}</h2><button type="button" class="close" data-close="action-dialog" aria-label="Закрыть">×</button></div>${teacherFields(t||{})}${t?.has_portrait?'<button type="button" class="text-button danger-text" id="teacher-photo-remove">Убрать портрет</button>':''}<p class="muted small">Изменения карточки будут доступны всем классам школы. Готовые макеты обновляются отдельно.</p><p class="error" role="alert"></p><button class="primary wide" type="submit">Сохранить</button></form>`;
    $('#action-dialog').showModal();const f=$('#teacher-edit');f.elements.last_name.focus();
    f.onsubmit=async e=>{e.preventDefault();const b=f.querySelector('[type=submit]');b.disabled=true;try{await api(t?'/teachers/'+t.id:`/schools/${school.id}/teachers`,json(t?'PATCH':'POST',Object.fromEntries(new FormData(f))));$('#action-dialog').close();await refresh();toast('Учитель сохранён');}catch(error){f.querySelector('.error').textContent=error.message;}finally{b.disabled=false;}};
    const drop=$('#teacher-photo-remove');if(drop)drop.onclick=async()=>{if(!confirm('Убрать портрет из карточки? Готовые макеты сохранят своё фото.'))return;try{await api(`/teachers/${t.id}/portrait`,{method:'DELETE'});$('#action-dialog').close();await refresh();toast('Портрет убран');}catch(error){f.querySelector('.error').textContent=error.message;}};
  }
  function mergeDialog(school,t,refresh=()=>schoolPage(school.id)){
    const candidates=school.teachers.filter(x=>x.id!==t.id);if(!candidates.length){toast('Нет другой карточки для объединения');return;}
    $('#action-content').innerHTML=`<form id="teacher-merge"><div class="dialog-heading"><h2>Объединить карточки</h2><button type="button" class="close" data-close="action-dialog" aria-label="Закрыть">×</button></div><p>Карточка «${esc(t.name)}» уйдёт в архив. Её заказы перейдут выбранной карточке. В ней сохранятся ФИО и фото; если фото нет, используем исходное.</p><label>Оставить карточку<select name="target_id" required><option value="">Выберите учителя</option>${candidates.map(x=>`<option value="${esc(x.id)}">${esc(x.name)} · ${esc(x.subject)}</option>`).join('')}</select></label><p class="error" role="alert"></p><button class="primary" type="submit">Объединить</button></form>`;$('#action-dialog').showModal();const f=$('#teacher-merge');f.onsubmit=async e=>{e.preventDefault();const b=f.querySelector('button[type=submit]');b.disabled=true;try{await api(`/teachers/${t.id}/merge`,json('POST',Object.fromEntries(new FormData(f))));$('#action-dialog').close();await refresh();toast('Карточки объединены');}catch(error){f.querySelector('.error').textContent=error.message;}finally{b.disabled=false;}};
  }
  async function schoolPage(id){
    const version=routeVersion;$('#main').innerHTML='<div class="page"><p class="muted">Загружаем школу…</p></div>';
    let school;try{school=await api('/schools/'+encodeURIComponent(id));}catch(error){if(version===routeVersion)$('#main').innerHTML=`<div class="page"><h1>Не удалось открыть школу</h1><p class="error">${esc(error.message)}</p><a class="secondary" href="#schools">К каталогу</a></div>`;return;}if(version!==routeVersion)return;
    const view=schoolViews.get(id)||{tab:'photos',query:'',filter:'all'};schoolViews.set(id,view);
    const teachers=[...school.teachers,...(school.archived_teachers||[])];
    $('#main').innerHTML=`<div class="page schools-page"><div class="eyebrow"><a href="#schools">Каталог школ</a> / ${esc(school.city||'Укажите город')}</div><div class="page-heading"><div><h1 class="school-title">${esc(school.name)}</h1><p class="muted">${place(school)} · ${teacherLabel(school.teacher_count)} · ${orderLabel(school.order_count)}</p></div><div class="school-heading-actions"><button class="primary" data-school-order>Создать заказ</button><button class="secondary" data-school="edit">Изменить</button>${school.order_count?'':'<button class="danger-button" data-school="delete">Удалить</button>'}</div></div><div class="workspace-tabs school-tabs" role="tablist">${[['photos','Съёмки'],['teachers','Учителя'],['orders','Заказы']].map(([key,label])=>`<button role="tab" data-school-tab="${key}" aria-selected="${view.tab===key}">${label}</button>`).join('')}</div><section data-school-panel="teachers"><div class="teacher-toolbar"><label>Поиск учителя<input id="teacher-query" type="search" placeholder="ФИО или предмет" value="${esc(view.query)}"></label><label>Показать<select id="teacher-filter">${[['all','Все действующие'],['missing','Без портрета'],['client','Подписано классом'],['archived','В архиве']].map(([k,l])=>`<option value="${k}" ${view.filter===k?'selected':''}>${l}</option>`).join('')}</select></label><button class="primary" data-teacher-new>Добавить учителя</button></div><div id="teacher-results" class="teacher-grid"></div></section><section data-school-panel="photos" hidden><div class="tphoto-panel" id="school-teacher-photos"></div></section><section data-school-panel="orders" hidden><div class="school-list">${school.orders.map(o=>`<a class="school-card" href="#order/${encodeURIComponent(o.id)}/teachers"><strong>${esc(o.class_name)}</strong><span>${o.graduation_year||''}</span><span class="muted">${esc(stageLabel(o.stage))}</span><span>Открыть →</span></a>`).join('')||'<p class="muted">Заказов пока нет. Создайте первый заказ для этой школы.</p>'}</div></section></div>`;
    const main=$('#main .schools-page');let photosLoaded=false;
    const showTab=()=>{main.querySelectorAll('[data-school-panel]').forEach(el=>{el.hidden=el.dataset.schoolPanel!==view.tab;});main.querySelectorAll('[data-school-tab]').forEach(el=>el.setAttribute('aria-selected',String(el.dataset.schoolTab===view.tab)));if(view.tab==='photos'&&!photosLoaded){photosLoaded=true;teacherPhotos($('#school-teacher-photos'),school.id);}};
    const draw=()=>{const q=searchKey(view.query),rows=teachers.filter(t=>(view.filter==='archived'?t.archived:!t.archived)&&(!q||searchKey(t.name+' '+t.subject).includes(q))&&(view.filter!=='missing'||!t.has_portrait)&&(view.filter!=='client'||t.portrait_by==='client'));$('#teacher-results').innerHTML=rows.map(teacherCard).join('')||'<div class="empty-state"><h3>Учителей нет</h3><p>Добавьте учителя или измените условия поиска.</p></div>';};draw();showTab();
    $('#teacher-query').oninput=e=>{view.query=e.target.value;draw();};$('#teacher-filter').onchange=e=>{view.filter=e.target.value;draw();};
    main.onchange=async e=>{const input=e.target.closest('[data-teacher-photo]');if(!input||!input.files[0])return;const file=input.files[0];input.value='';const card=input.closest('.teacher-card');card.classList.add('busy');try{await api(`/teachers/${encodeURIComponent(input.dataset.teacherPhoto)}/portrait`,{method:'PUT',headers:{'Content-Type':file.type||'application/octet-stream'},body:file});await schoolPage(school.id);toast('Портрет сохранён');}catch(error){card.classList.remove('busy');toast(error.message);}};
    main.onclick=async e=>{
      const tab=e.target.closest('[data-school-tab]');if(tab){const previous=view.tab;view.tab=tab.dataset.schoolTab;if(previous==='photos'&&view.tab!=='photos'){schoolPage(id);return;}showTab();return;}
      if(e.target.closest('[data-school-order]')){openNew(school);return;}
      if(e.target.closest('[data-school="edit"]')){schoolForm(school);return;}
      if(e.target.closest('[data-school="delete"]')){if(!confirm(`Удалить школу «${school.name}» вместе с учителями и фотографиями?`))return;try{await api('/schools/'+school.id,{method:'DELETE'});location.hash='schools';toast('Школа удалена');}catch(error){toast(error.message);}return;}
      if(e.target.closest('[data-teacher-new]')){teacherEditor(school);return;}
      const action=e.target.closest('[data-teacher-edit],[data-teacher-delete],[data-teacher-restore],[data-teacher-merge]');if(!action)return;
      const key=['teacherEdit','teacherDelete','teacherRestore','teacherMerge'].find(k=>action.dataset[k]),t=teachers.find(t=>t.id===action.dataset[key]);
      if(key==='teacherEdit'){teacherEditor(school,t);return;}if(key==='teacherMerge'){mergeDialog(school,t);return;}
      if(key==='teacherDelete'&&!confirm(`Отправить ${t.name} в архив? В существующих заказах учитель останется. Его можно восстановить.`))return;
      action.disabled=true;try{await api('/teachers/'+t.id+(key==='teacherRestore'?'/restore':''),{method:key==='teacherRestore'?'POST':'DELETE'});await schoolPage(school.id);toast(key==='teacherRestore'?'Учитель восстановлен':'Учитель в архиве');}catch(error){toast(error.message);action.disabled=false;}
    };
  }

  function page(id){if(id)schoolPage(id);else listPage();}

  // Teacher photos: uploaded from the catalogue or from an order of the school, then each is given to a teacher.
  const uploads={};
  const isImage=f=>/^image\/(jpe?g|pjpeg|png|x-png)$/i.test(f.type||'')||/\.(jpe?g|png)$/i.test(f.name);
  async function upload(schoolId,files,orderId=null,shootId=null){
    files=[...files].filter(isImage);if(!files.length){toast('Выберите файлы JPG или PNG');return;}
    if(!shootId){const folder=files[0]?.webkitRelativePath?.split('/')[0];const shotOn=await PhotoTools.guessDate(files).catch(()=>null)||'';try{const shoot=await api(`/schools/${encodeURIComponent(schoolId)}/teacher-shoots`,json('POST',{title:(folder||'Учителя').slice(0,100),shot_on:shotOn}));shootId=shoot.id;}catch(error){toast(error.message);return;}}
    if(orderId&&state.order?.id===orderId){await uploadFiles(files,'teachers',shootId);return;}
    const run=uploads[schoolId]||(uploads[schoolId]={total:0,done:0,duplicates:0,errors:[],queue:[],active:false});
    run.total+=files.length;run.queue.push(...files.map(file=>({file,orderId,shootId})));drawProgress(schoolId);
    if(run.active)return;run.active=true;
    const worker=async()=>{while(run.queue.length){const {file,orderId,shootId}=run.queue.shift();try{if(file.size>30*1024*1024)throw Error('Файл больше 30 МБ');const result=await api(`/schools/${encodeURIComponent(schoolId)}/teacher-photos?filename=${encodeURIComponent(file.name)}${orderId?'&order_id='+encodeURIComponent(orderId):''}&shoot_id=${encodeURIComponent(shootId)}`,{method:'POST',headers:{'Content-Type':'application/octet-stream'},body:file});if(result.duplicate)run.duplicates++;}catch(error){run.errors.push(file.name+': '+error.message);}run.done++;drawProgress(schoolId);}};
    await Promise.all(Array.from({length:3},worker));
    run.active=false;toast(run.errors.length?'Загрузка завершена с ошибками':`Загружено: ${run.done-run.errors.length-run.duplicates}. Пропущено дублей: ${run.duplicates}. Обработка фотографий продолжается.`);
    const errors=run.errors;delete uploads[schoolId];
    const root=document.querySelector(`[data-teacher-photos="${CSS.escape(schoolId)}"]`);if(root)await teacherPhotos(root,schoolId,root.dataset.tphotoOrder||null,errors);
  }
  function drawProgress(schoolId){const el=document.querySelector(`[data-teacher-photos="${CSS.escape(schoolId)}"] .teacher-upload-progress`),run=uploads[schoolId];if(el&&run)el.innerHTML=`<span>Загружаем ${run.done} из ${run.total}</span><progress max="${run.total}" value="${run.done}"></progress>`;}

  const tphotoSrc=id=>`/api/teacher-photos/${encodeURIComponent(id)}/thumb`;
  const polls=new WeakMap(),photoViews=new Map();
  function groupCard(g,i){
    const cover=g.photos.find(p=>p.id===g.selected_photo_id)||g.photos[0],pending=g.photos.some(p=>!['ready','signed'].includes(p.status));
    return `<article class="folder teacher-group"><button type="button" class="folder-open" data-open-group="${esc(g.id)}">${cover?`<img src="${tphotoSrc(cover.id)}" alt="" loading="lazy">`:`<span class="folder-empty">${svgIcon('user',28)}</span>`}<strong>${esc(g.name||`Учитель ${i+1}`)}</strong><small>${count(g.photos.length,'кадр','кадра','кадров')}</small><span class="teacher-frame-status${g.selected_photo_id?' ready':''}">${svgIcon(pending?'clock':g.selected_photo_id?'check':'photo',14)}${pending?'Обработка':g.signed?'Подписан':g.published?'Открыто классу':g.selected_photo_id?'Кадр выбран':'Выберите кадр'}</span></button></article>`;
  }
  function openGroup(group,groups,teachers,refresh){
    const dialog=$('#action-dialog');dialog.classList.add('wide-dialog');
    let current=group.selected_photo_id||group.photos.find(p=>p.status==='ready')?.id||group.photos[0]?.id;
    $('#action-content').innerHTML=`<div class="dialog-heading"><div><h2>Фото учителя</h2><p class="muted small">Выберите кадр и подпишите сами или попросите класс.</p></div><button type="button" class="close" data-close="action-dialog" aria-label="Закрыть">×</button></div><div class="teacher-review"><div><div class="teacher-review-image"><img id="teacher-review-full" src="/api/teacher-photos/${encodeURIComponent(current)}/full" alt="Фото учителя"><button type="button" class="secondary teacher-zoom-toggle" data-teacher-zoom>${svgIcon('search',16)} Приблизить</button></div><div class="teacher-filmstrip">${group.photos.map((p,i)=>`<button type="button" data-frame="${esc(p.id)}" class="${p.id===current?'chosen':''}" ${!['ready','signed'].includes(p.status)?'disabled':''} aria-label="Кадр ${i+1}" aria-pressed="${p.id===current}"><img src="${tphotoSrc(p.id)}" alt="" loading="lazy"></button>`).join('')}</div><button type="button" class="text-button" data-group-edit ${group.signed?'hidden':''}>${svgIcon('edit',16)} Исправить группу</button><div class="teacher-group-edit" hidden>${group.photos.map(p=>`<label>${esc(p.filename)}<select data-move="${esc(p.id)}"><option value="">Переместить…</option>${groups.filter(g=>g.id!==group.id&&!g.signed&&g.photos[0]?.shoot_id===group.photos[0]?.shoot_id).map((g,i)=>`<option value="${esc(g.id)}">Учитель ${groups.indexOf(g)+1}</option>`).join('')}<option value="__alone">Отдельная группа</option></select><button type="button" class="text-button danger-text" data-tphoto-delete="${esc(p.id)}">${svgIcon('trash',14)} Удалить</button></label>`).join('')}</div></div><form id="teacher-frame-form" class="teacher-review-form"><button type="button" class="primary" data-frame-save>${svgIcon('check',16)} Сохранить выбранный кадр</button><a class="text-button" data-frame-download href="/api/teacher-photos/${encodeURIComponent(current)}/full" download="teacher.jpg">${svgIcon('download',16)} Скачать кадр</a><p class="muted small">Имя можно указать позже. Класс увидит только сохранённый кадр после нажатия «Попросить класс подписать».</p><label>Кто это?<select name="assign"><option value="">Подписать позже</option>${teachers.map(t=>`<option value="${esc(t.id)}">${esc(t.name)}${t.has_portrait?' · заменить портрет':''}</option>`).join('')}<option value="new">Новый учитель</option></select></label><div class="tphoto-new" hidden>${teacherFields()}</div><button type="submit" class="secondary" hidden data-name-save>Сохранить имя и портрет</button><p class="error" role="alert"></p></form></div>`;
    if(!dialog.open)dialog.showModal();const form=$('#teacher-frame-form'),error=form.querySelector('.error');
    const request=async(button,action,finish=true)=>{button.disabled=true;error.textContent='';try{await action();if(finish){dialog.close();dialog.onkeydown=null;$('#action-content').onclick=null;$('#action-content').onchange=null;dialog.classList.remove('wide-dialog');await refresh();}}catch(e){error.textContent=e.message;}finally{button.disabled=false;}};
    form.elements.assign.onchange=()=>{const isNew=form.elements.assign.value==='new';form.querySelector('.tphoto-new').hidden=!isNew;form.querySelector('[data-name-save]').hidden=!form.elements.assign.value;form.querySelectorAll('.tphoto-new input').forEach(el=>el.disabled=!isNew);};form.elements.assign.onchange();if(group.teacher_id){form.elements.assign.value=group.teacher_id;form.elements.assign.onchange();}
    form.onsubmit=e=>{e.preventDefault();const id=form.elements.assign.value;if(!id)return;const t=teachers.find(t=>t.id===id);if(t?.has_portrait&&!confirm(`Заменить портрет: ${t.name}?`))return;const body=id==='new'?{teacher:Object.fromEntries(new FormData(form))}:{teacher_id:id};request(form.querySelector('[type=submit]'),()=>api(`/teacher-photos/${encodeURIComponent(current)}/assign`,json('POST',body)));};
    dialog.onkeydown=e=>{if(e.target.matches('input,select,textarea'))return;if(e.key==='ArrowLeft'||e.key==='ArrowRight'){const frames=[...dialog.querySelectorAll('[data-frame]:not(:disabled)')],i=frames.findIndex(el=>el.dataset.frame===current),next=frames[(i+(e.key==='ArrowRight'?1:-1)+frames.length)%frames.length];if(next){e.preventDefault();next.click();}}};
    $('#action-content').onclick=e=>{const frame=e.target.closest('[data-frame]');if(frame){current=frame.dataset.frame;$('#teacher-review-full').src=`/api/teacher-photos/${encodeURIComponent(current)}/full`;$('#teacher-review-full').classList.remove('zoomed');dialog.querySelector('[data-frame-download]').href=`/api/teacher-photos/${encodeURIComponent(current)}/full`;dialog.querySelectorAll('[data-frame]').forEach(el=>{el.classList.toggle('chosen',el===frame);el.setAttribute('aria-pressed',String(el===frame));});return;}
      const save=e.target.closest('[data-frame-save]');if(save){request(save,()=>api(`/teacher-photos/${encodeURIComponent(current)}/select`,json('POST',{})));return;}
      const zoom=e.target.closest('[data-teacher-zoom]');if(zoom){const enlarged=$('#teacher-review-full').classList.toggle('zoomed');zoom.innerHTML=svgIcon('search',16)+(enlarged?' Вписать':' Приблизить');return;}
      if(e.target.closest('[data-group-edit]')){const el=dialog.querySelector('.teacher-group-edit');el.hidden=!el.hidden;return;}
      const del=e.target.closest('[data-tphoto-delete]');if(del&&confirm('Удалить этот кадр?'))request(del,()=>api(`/teacher-photos/${encodeURIComponent(del.dataset.tphotoDelete)}`,{method:'DELETE'}));};
    $('#action-content').onchange=e=>{const move=e.target.closest('[data-move]');if(move?.value)request(move,()=>api(`/teacher-photos/${encodeURIComponent(move.dataset.move)}/move`,json('POST',{group_id:move.value==='__alone'?null:move.value})));};
  }
  async function teacherPhotos(root,schoolId,orderId=null,errors=[]){
    root.dataset.teacherPhotos=schoolId;if(orderId)root.dataset.tphotoOrder=orderId;clearTimeout(polls.get(root));
    let pool,school;try{[pool,school]=await Promise.all([api(`/schools/${encodeURIComponent(schoolId)}/teacher-photos`),api(`/schools/${encodeURIComponent(schoolId)}`)]);}catch(error){if(root.isConnected)root.innerHTML=`<p class="error">${esc(error.message)}</p>`;return;}if(!root.isConnected)return;
    const view=photoViews.get(schoolId)||{shoot:orderId?'all':'overview',filter:'all'};photoViews.set(schoolId,view);
    const groups=[...pool.groups,...(pool.signed_groups||[])],ready=groups.filter(g=>!g.signed&&g.selected_photo_id&&!g.published&&g.photos.every(p=>p.status==='ready')).length;
    if(view.shoot!=='all'&&view.shoot!=='overview'&&view.shoot!=='legacy'&&!pool.shoots.some(s=>s.id===view.shoot))view.shoot='overview';
    const scoped=groups.filter(g=>view.shoot==='all'||g.photos.some(p=>(p.shoot_id||'legacy')===view.shoot));
    const visible=scoped.filter(g=>view.filter==='all'||view.filter==='choose'&&!g.selected_photo_id||view.filter==='selected'&&g.selected_photo_id||view.filter==='pending'&&g.photos.some(p=>!['ready','signed'].includes(p.status)));
    const shoots=[...pool.shoots];if(groups.some(g=>g.photos.some(p=>!p.shoot_id)))shoots.push({id:'legacy',title:'Ранее загруженные фото',shot_on:'',preview_id:groups.flatMap(g=>g.photos).find(p=>!p.shoot_id)?.id});
    root.innerHTML=`<div class="shoot-head">${orderId&&state.view==='photos'?`<button type="button" class="shoot-back" data-teacher-back aria-label="Все съёмки">${svgIcon('back',18)}</button>`:''}<h2>${svgIcon('school',20)} Учителя школы <span class="muted">${groups.length}</span></h2><div class="tphoto-buttons"><label class="primary">${svgIcon('upload',16)} Загрузить фото<input type="file" accept="image/jpeg,image/png,.jpg,.jpeg,.png" multiple hidden data-tupload></label><label class="secondary">${svgIcon('folder',16)} Папку<input type="file" webkitdirectory multiple hidden data-tupload></label></div></div><p class="muted small">Выберите портрет каждого учителя. Подпишите сами или откройте выбранные фото всем классам школы.</p><div class="teacher-upload-progress"></div>${errors.length?`<details class="error small"><summary>Не загружено: ${errors.length}</summary>${errors.map(e=>`<div>${esc(e)}</div>`).join('')}</details>`:''}${orderId?`<div class="teacher-workspace-tabs filter-chips"><button type="button" data-teacher-view="frames" class="${view.filter!=='catalog'?'active':''}">${svgIcon('photo',16)} Фото</button><button type="button" data-teacher-view="catalog" class="${view.filter==='catalog'?'active':''}">${svgIcon('users',16)} Учителя <small>${school.teachers.length}</small></button></div>`:''}${view.filter==='catalog'?`<div class="teacher-grid">${school.teachers.map(teacherCard).join('')||'<div class="empty-state"><h3>Учителей пока нет</h3><p>Откройте съёмку и подпишите выбранные портреты.</p></div>'}</div>`:`<div class="teacher-shoots filter-chips"><button type="button" data-teacher-shoot="overview" class="${view.shoot==='overview'?'active':''}">${svgIcon('folder',16)} Съёмки</button><button type="button" class="${view.shoot==='all'?'active':''}" data-teacher-shoot="all">Все съёмки</button>${shoots.map(s=>`<button type="button" data-teacher-shoot="${esc(s.id)}" class="${view.shoot===s.id?'active':''}">${esc(s.title)}${s.shot_on?` <small>${esc(fmtDate(s.shot_on))}</small>`:''}</button>`).join('')}</div><div class="shoot-bar"><div class="filter-chips">${[['all','Все'],['choose','Выбрать кадр'],['selected','Кадр выбран'],['pending','Обработка']].map(([key,label])=>`<button type="button" data-teacher-filter="${key}" class="${view.filter===key?'active':''}">${label}</button>`).join('')}</div><button type="button" class="secondary" data-teacher-publish ${ready?'':'disabled'}>${svgIcon('users',16)} Попросить класс подписать${ready?` · ${ready}`:''}</button></div><div class="folder-grid teacher-groups">${view.shoot==='overview'?shoots.map(s=>`<article class="folder"><button type="button" class="folder-open" data-teacher-shoot="${esc(s.id)}">${s.preview_id?`<img src="${tphotoSrc(s.preview_id)}" alt="" loading="lazy">`:`<span class="folder-empty">${svgIcon('photo',28)}</span>`}<strong>${esc(s.title)}</strong><small>${s.shot_on?esc(fmtDate(s.shot_on))+' · ':''}${s.photo_count||groups.filter(g=>g.photos.some(p=>!p.shoot_id)).reduce((n,g)=>n+g.photos.length,0)} фото</small></button>${s.id!=='legacy'?`<div class="design-menu folder-menu"><button type="button" class="design-menu-toggle" data-teacher-menu aria-haspopup="menu" aria-expanded="false" aria-label="Действия со съёмкой ${esc(s.title)}">${svgIcon('more',18)}</button><div class="design-menu-list" role="menu" hidden><button type="button" role="menuitem" data-teacher-shoot-edit="${esc(s.id)}">${svgIcon('edit',16)} Изменить съёмку</button></div></div>`:''}</article>`).join('')||'<div class="empty-state"><h3>Добавьте съёмку учителей</h3><p>Загрузите фото или папку. Имя папки и дата фотографий помогут назвать съёмку.</p></div>':visible.map(g=>groupCard(g,groups.indexOf(g))).join('')||`<div class="empty-state"><h3>${groups.length?'Здесь нет фотографий':'Добавьте фотографии учителей'}</h3><p>${groups.length?'Выберите другую съёмку или фильтр.':'Загрузите готовые портреты или несколько кадров — они соберутся по людям.'}</p></div>`}</div>`}${pool.assignments?.length?`<details class="teacher-history"><summary>История подписей</summary>${pool.assignments.map(a=>`<div><span>${esc([a.last_name,a.first_name,a.patronymic].filter(Boolean).join(' '))}</span><button type="button" class="text-button" data-undo-assignment="${esc(a.id)}">Отменить подпись</button></div>`).join('')}</details>`:''}`;
    if(orderId){const slot=root.querySelector('.teacher-upload-progress');slot.id='upload-status';renderProgress();}else drawProgress(schoolId);
    root.ondragover=e=>{if(e.dataTransfer?.types.includes('Files')){e.preventDefault();e.stopPropagation();root.classList.add('dragging');}};root.ondragleave=e=>{if(!root.contains(e.relatedTarget))root.classList.remove('dragging');};root.ondrop=async e=>{e.preventDefault();e.stopPropagation();root.classList.remove('dragging');await upload(schoolId,await PhotoTools.filesFrom(e.dataTransfer),orderId,!['all','overview','legacy'].includes(view.shoot)?view.shoot:null);};
    const refresh=()=>teacherPhotos(root,schoolId,orderId);
    root.onchange=async e=>{e.stopPropagation();if(e.target.matches('[data-tupload]')){const files=[...e.target.files];e.target.value='';await upload(schoolId,files,orderId,!['all','overview','legacy'].includes(view.shoot)?view.shoot:null);return;}const input=e.target.closest('[data-teacher-photo]');if(input?.files[0]){const file=input.files[0];input.value='';try{await api(`/teachers/${encodeURIComponent(input.dataset.teacherPhoto)}/portrait`,{method:'PUT',body:file});refresh();}catch(error){toast(error.message);}}};
    root.onclick=async e=>{e.stopPropagation();
      if(e.target.closest('[data-teacher-back]')){state.shootId=null;renderWorkspace();return;}
      const menu=e.target.closest('[data-teacher-menu]');if(menu){const parent=menu.closest('.design-menu'),list=parent.querySelector('.design-menu-list');const open=list.hidden;closeDesignMenus();parent.classList.toggle('open',open);list.hidden=!open;menu.setAttribute('aria-expanded',String(open));return;}
      const editShoot=e.target.closest('[data-teacher-shoot-edit]');if(editShoot){const shoot=shoots.find(s=>s.id===editShoot.dataset.teacherShootEdit);closeDesignMenus();$('#action-content').onclick=null;$('#action-content').onchange=null;$('#action-content').innerHTML=`<form id="teacher-shoot-edit"><div class="dialog-heading"><h2>Изменить съёмку</h2><button type="button" class="close" data-close="action-dialog" aria-label="Закрыть">×</button></div><label>Название<input name="title" maxlength="100" value="${esc(shoot.title)}" required></label><label>Дата съёмки<input type="date" name="shot_on" value="${esc(shoot.shot_on)}"></label><p class="error" role="alert"></p><button type="submit" class="primary">Сохранить</button></form>`;$('#action-dialog').showModal();const f=$('#teacher-shoot-edit');f.onsubmit=async ev=>{ev.preventDefault();const b=f.querySelector('[type=submit]');b.disabled=true;try{await api(`/schools/${encodeURIComponent(schoolId)}/teacher-shoots/${encodeURIComponent(shoot.id)}`,json('PATCH',Object.fromEntries(new FormData(f))));$('#action-dialog').close();await refresh();}catch(error){f.querySelector('.error').textContent=error.message;b.disabled=false;}};return;}
      const group=e.target.closest('[data-open-group]');if(group){openGroup(groups.find(g=>g.id===group.dataset.openGroup),groups,school.teachers,refresh);return;}const filter=e.target.closest('[data-teacher-filter]');if(filter){view.filter=filter.dataset.teacherFilter;refresh();return;}const tab=e.target.closest('[data-teacher-view]');if(tab){view.filter=tab.dataset.teacherView==='catalog'?'catalog':'all';refresh();return;}const shoot=e.target.closest('[data-teacher-shoot]');if(shoot){view.shoot=shoot.dataset.teacherShoot;refresh();return;}const publish=e.target.closest('[data-teacher-publish]');if(publish){publish.disabled=true;try{const result=await api(`/schools/${encodeURIComponent(schoolId)}/teacher-photos/publish`,json('POST',{}));toast(`Открыто для подписи: ${result.published}`);await refresh();}catch(error){toast(error.message);publish.disabled=false;}return;}const undo=e.target.closest('[data-undo-assignment]');if(undo){try{await api(`/teacher-assignments/${encodeURIComponent(undo.dataset.undoAssignment)}/undo`,json('POST',{}));await refresh();}catch(error){toast(error.message);}return;}
      const edit=e.target.closest('[data-teacher-edit]');if(edit){teacherEditor(school,school.teachers.find(t=>t.id===edit.dataset.teacherEdit),refresh);return;}const archive=e.target.closest('[data-teacher-delete]');if(archive&&confirm('Отправить учителя в архив?')){try{await api(`/teachers/${encodeURIComponent(archive.dataset.teacherDelete)}`,{method:'DELETE'});await refresh();}catch(error){toast(error.message);}return;}const merge=e.target.closest('[data-teacher-merge]');if(merge)mergeDialog(school,school.teachers.find(t=>t.id===merge.dataset.teacherMerge),refresh);};
    if(pool.pending||uploads[schoolId]?.active){const poll=()=>{if(!root.isConnected)return;if($('#action-dialog').open||root.contains(document.activeElement)){polls.set(root,setTimeout(poll,3000));return;}refresh();};polls.set(root,setTimeout(poll,3000));}
  }

  // Order photos tab: the "Учителя" folder shows the school's teacher photos.
  async function folderPreview(order){
    if(!order.school_id)return;
    const root=document.querySelector('[data-teacher-folder-preview]');if(!root)return;
    try{const school=await api(`/schools/${encodeURIComponent(order.school_id)}`);if(!root.isConnected)return;
      if(school.previews?.length)root.innerHTML=`<span class="order-preview-fan count-${school.previews.length}">${school.previews.map(t=>`<img src="${portraitUrl(t)}" alt="" loading="lazy">`).join('')}</span>`;
    }catch{}
  }
  function orderFolder(order){
    const root=document.createElement('div');root.className='tphoto-panel';
    if(!order.school_id){root.innerHTML='<div class="empty-state"><h3>Школа не из каталога</h3><p>Чтобы загрузить фото учителей, выберите школу заказа из каталога: «⋯ → Изменить заказ».</p></div>';return root;}
    root.innerHTML='<p class="muted">Загружаем фото учителей…</p>';teacherPhotos(root,order.school_id,order.id);return root;
  }

  // Order page (Анкеты tab): teachers chosen for this class album.
  async function orderBlock(order){
    const el=$('#order-teachers');if(!el)return;const id=order.id;
    let data;try{data=await api(`/orders/${encodeURIComponent(id)}/teachers`);}catch(error){el.innerHTML=`<p class="error">${esc(error.message)}</p>`;return;}
    if(state.order?.id!==id||!$('#order-teachers'))return;
    if(!data.school){el.innerHTML='<p class="muted small">Школа заказа не выбрана из каталога. Откройте «⋯ → Изменить заказ» и выберите школу, чтобы класс мог отметить учителей.</p>';return;}
    if(!data.teachers.length){el.innerHTML=`<p class="muted small">В каталоге у школы «${esc(data.school.name)}» пока нет учителей.${data.layout_outdated?' Макет содержит прежние данные — обновите его.':''} <a href="#order/${encodeURIComponent(id)}/teachers">Загрузить фотографии →</a></p>`;return;}
    const picked=data.teachers.filter(t=>t.selected).length;
    const lead=data.teachers.find(t=>t.is_class_teacher);const who=`Выбрано ${teacherLabel(picked)}${lead?' · Классный руководитель: '+esc(lead.name):''}`;
    if(state.view==='client'){
      const selected=data.teachers.filter(t=>t.selected);
      el.innerHTML=`<p class="muted small">${who}</p><div class="teacher-selection-summary">${selected.slice(0,8).map(t=>`<span class="teacher-photo small" title="${esc(t.name)}">${avatar(t)}</span>`).join('')}${picked>8?`<span class="muted small">+${picked-8}</span>`:''}<a class="text-button" href="#order/${encodeURIComponent(id)}/teachers">${svgIcon('edit',16)} Изменить список</a></div>`;return;
    }
    el.innerHTML=`<p class="muted small">${who}</p>${data.unsigned_groups?`<p class="warn small">Не подписано учителей на фото: ${data.unsigned_groups}. Откройте выбранные кадры классу или подпишите сами. <a href="#order/${encodeURIComponent(id)}/teachers" class="text-button">Открыть фотографии →</a></p>`:''}${data.layout_outdated?'<p class="warn small">Данные школы или учителей изменились после сборки. Обновите макет, чтобы применить изменения.</p>':''}<form id="order-teachers-form"><div class="teacher-choice-list">${data.teachers.map(t=>`<div class="teacher-choice"><label class="teacher-choice-main"><input type="checkbox" name="teacher" value="${esc(t.id)}" ${t.selected?'checked':''} ${data.locked?'disabled':''}><span class="teacher-photo small">${avatar(t)}</span><span><strong>${esc(t.name)}</strong><small>${t.archived?'В архиве · ':''}${t.has_portrait?'':'Нет портрета · '}${esc(t.subject)}</small></span></label><label class="teacher-subject">Предмет в этом классе<input data-subject="${esc(t.id)}" maxlength="100" value="${esc(t.subject)}" ${data.locked?'disabled':''}></label><label class="teacher-lead"><input type="radio" name="lead" value="${esc(t.id)}" ${t.is_class_teacher?'checked':''} ${data.locked?'disabled':''}>Кл. руководитель</label></div>`).join('')}</div>${data.locked?'<p class="muted small">Заказ в печати — состав учителей зафиксирован.</p>':'<button type="button" class="text-button" data-clear-lead>Снять назначение классного руководителя</button><p class="error" role="alert"></p><button class="secondary" type="submit">Сохранить учителей</button>'}</form>`;
    const form=$('#order-teachers-form'),draftKey='photographer-teachers-'+id;
    if(data.locked)return;
    let draft;try{draft=JSON.parse(sessionStorage.getItem(draftKey)||'null');}catch{}
    if(draft?.school===data.school.id){form.querySelectorAll('[name=teacher]').forEach(el=>el.checked=draft.ids.includes(el.value));form.querySelectorAll('[name=lead]').forEach(el=>el.checked=draft.lead===el.value);form.querySelectorAll('[data-subject]').forEach(el=>{if(draft.subjects[el.dataset.subject]!==undefined)el.value=draft.subjects[el.dataset.subject];});}
    const remember=()=>{const ids=[...form.querySelectorAll('[name=teacher]:checked')].map(el=>el.value);try{sessionStorage.setItem(draftKey,JSON.stringify({school:data.school.id,ids,lead:form.querySelector('[name=lead]:checked')?.value||null,subjects:Object.fromEntries([...form.querySelectorAll('[data-subject]')].map(el=>[el.dataset.subject,el.value]))}));}catch{}};
    form.querySelector('[data-clear-lead]').onclick=()=>{form.querySelectorAll('[name=lead]').forEach(el=>el.checked=false);remember();};
    form.oninput=remember;
    form.onchange=e=>{if(e.target.name==='lead'&&e.target.checked){const box=form.querySelector(`[name=teacher][value="${CSS.escape(e.target.value)}"]`);if(box)box.checked=true;}if(e.target.name==='teacher'&&!e.target.checked){const lead=form.querySelector(`[name=lead][value="${CSS.escape(e.target.value)}"]`);if(lead)lead.checked=false;}remember();};
    form.onsubmit=async e=>{e.preventDefault();const ids=[...form.querySelectorAll('[name=teacher]:checked')].map(x=>x.value),lead=form.querySelector('[name=lead]:checked')?.value||null;try{await api(`/orders/${encodeURIComponent(id)}/teachers`,json('PUT',{teacher_ids:ids,class_teacher_id:lead,subjects:Object.fromEntries([...form.querySelectorAll('[data-subject]')].filter(el=>ids.includes(el.dataset.subject)).map(el=>[el.dataset.subject,el.value]))}));try{sessionStorage.removeItem(draftKey);}catch{}toast('Учителя сохранены');orderBlock(order);}catch(error){form.querySelector('.error').textContent=error.message;}};
  }

  function orderPage(order){
    $('#workspace').innerHTML='<div id="order-teacher-photo-workspace"></div><details class="forms-block"><summary>Выбранные учителя класса</summary><div id="order-teachers"></div></details>';
    $('#order-teacher-photo-workspace').append(orderFolder(order));
    orderBlock(order);const details=$('#workspace details');$('#workspace').addEventListener('click',e=>{if(e.target.closest('[data-order-photo-open]')){details.open=true;details.scrollIntoView({block:'start',behavior:'smooth'});}});
  }

  document.addEventListener('click',e=>{if(e.target.closest('[data-school="new"]'))schoolForm(null);if(e.target.closest('[data-v2-teachers]'))state.shootId='teachers';});
  // After an order upload of teacher files: redraw the open folders so new frames and groups show.
  const refreshFolders=()=>document.querySelectorAll('[data-teacher-photos]').forEach(root=>teacherPhotos(root,root.dataset.teacherPhotos,root.dataset.tphotoOrder||null));
  return {page,orderBlock,upload,orderFolder,orderPage,refreshFolders,folderPreview};
})();
